using System;
using System.Collections.Generic;
using System.Drawing;
using System.IO;
using System.Windows.Forms;
namespace ScopeMaker {
public partial class MainWindow {
 PointF pan; bool panning,spacePan; Point panLast; string lastProjectDirectory;
 void ResetView(){pan=PointF.Empty;SyncSceneScrollbars();canvas.Invalidate();}
 bool BeginPan(MouseEventArgs e){if(drawing||erasing||resizingImage||dragging)return false;if(e.Button!=MouseButtons.Middle&&!(spacePan&&e.Button==MouseButtons.Left))return false;panning=true;panLast=e.Location;canvas.Capture=true;canvas.Cursor=Cursors.Hand;return true;}
 void MovePan(Point point){pan.X+=point.X-panLast.X;pan.Y+=point.Y-panLast.Y;panLast=point;SyncSceneScrollbars();canvas.Invalidate();}
 void EndPan(){if(!panning)return;panning=false;canvas.Capture=false;canvas.Cursor=spacePan?Cursors.Hand:drawingTool.SelectedIndex==0?Cursors.Default:Cursors.Cross;canvas.Invalidate();}
 bool ViewKeyDown(KeyEventArgs e){if(!(canvas.ContainsFocus||panning))return false;if(e.KeyCode==Keys.Space){spacePan=true;canvas.Cursor=Cursors.Hand;e.SuppressKeyPress=true;return true;}if(e.KeyCode==Keys.Home&&!drawing&&!erasing&&!resizingImage){ResetView();e.SuppressKeyPress=true;return true;}return false;}
 void ViewKeyUp(object sender,KeyEventArgs e){if(e.KeyCode!=Keys.Space)return;spacePan=false;if(!panning)canvas.Cursor=drawingTool.SelectedIndex==0?Cursors.Default:Cursors.Cross;}
 string ProjectSaveDirectory(){return !String.IsNullOrEmpty(projectPath)?Path.GetDirectoryName(Path.GetFullPath(projectPath)):lastProjectDirectory??Environment.GetFolderPath(Environment.SpecialFolder.MyDocuments);}
 internal static string NextScopeName(string directory,string extension){long max=0;if(Directory.Exists(directory))foreach(string file in Directory.EnumerateFiles(directory,"scope_*"+extension)){string name=Path.GetFileNameWithoutExtension(file);long number;if(name.StartsWith("scope_",StringComparison.OrdinalIgnoreCase)&&Int64.TryParse(name.Substring(6),out number)&&number>max)max=number;}long next=checked(max+1);return "scope_"+next+extension;}
 public static void NavigationChecks(List<string> results){using(var w=new MainWindow()){w.Show();Application.DoEvents();w.snapGrid.Checked=false;string before=w.json.Serialize(w.Doc);int history=w.undo.Count;w.BeginPan(new MouseEventArgs(MouseButtons.Middle,1,100,100,0));w.MovePan(new Point(237,48));w.EndPan();foreach(int z in new[]{25,100,400}){w.zoom.Value=z;var point=w.Screen(.21,-.18,false,w.canvas.ClientRectangle);var world=w.World(Point.Round(point));if(Math.Abs(world.X-.21)>1/w.Scale(w.canvas.ClientRectangle)||Math.Abs(world.Y+.18)>1/w.Scale(w.canvas.ClientRectangle))throw new Exception("Pan inverse mapping");var frame=w.BackgroundFrame(w.canvas.ClientRectangle,new Size(800,600));var center=w.Screen(0,0,false,w.canvas.ClientRectangle);if(Math.Abs(frame.Left+frame.Width/2-center.X)>.01||Math.Abs(frame.Top+frame.Height/2-center.Y)>.01)throw new Exception("Pan alignment");}if(w.json.Serialize(w.Doc)!=before||w.dirty||w.undo.Count!=history)throw new Exception("Pan changed document");results.Add("PASS: Pan aligns background, reticle and inverse drawing coordinates at every zoom without document changes");w.ResetView();if(w.pan!=PointF.Empty)throw new Exception("Reset view");w.spacePan=true;if(!w.BeginPan(new MouseEventArgs(MouseButtons.Left,1,20,20,0)))throw new Exception("Space pan");w.CancelDrawing();if(w.panning||w.canvas.Capture)throw new Exception("Pan capture cleanup");results.Add("PASS: Space/middle pan, cancellation and center reset");w.dirty=false;w.Close();}
 string folder=Path.Combine(Path.GetTempPath(),"scope-names-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(folder);try{if(NextScopeName(folder,".blk")!="scope_1.blk")throw new Exception("First scope name");File.WriteAllText(Path.Combine(folder,"scope_1.blk"),"");File.WriteAllText(Path.Combine(folder,"scope_9.blk"),"");File.WriteAllText(Path.Combine(folder,"scope_bad.blk"),"");if(NextScopeName(folder,".blk")!="scope_10.blk"||NextScopeName(folder,".wtsm")!="scope_1.wtsm")throw new Exception("Scope numbering");results.Add("PASS: Sequential names skip existing numbers and separate projects from BLK");}finally{Directory.Delete(folder,true);}}
}
}
